[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:HowTo ;
                    schema1:step [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType <https://bioschemas.org/LabProcess> ;
                            schema1:description "Polished slabs of the irons; a mount of Zinder and a section of NWA 1911 for the pallasites (§2.1); no acid treatment is described for the LA-ICP-MS specimens" ;
                            schema1:name "Sample preparation" ;
                            schema1:position 1 ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType <https://bioschemas.org/LabProcess> ;
                            schema1:description "raster; Ge spots — 'Irons were analyzed using a raster scan over a few millimeters'; 'To obtain more precise Ge, a set of five 150 µm spots were analyzed at 50 Hz for 20 s on five of the irons' (§2.2)" ;
                            schema1:name "Data acquisition" ;
                            schema1:position 2 ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalProperty <https://ada.astromat.org/metadata/parameter/module/SingleCollector/pulseAnalogDetectorNonlinearityCorrectionDefault> ;
                            schema1:additionalType <https://bioschemas.org/LabProcess> ;
                            schema1:name "Data processing" ;
                            schema1:position 3 ;
                            ns1:detectionLimitMethod "no value available: ada:detectionLimitMethod" ] ] ;
            sh:resultMessage "A HowTo methodology must have a schema:name" ;
            sh:resultPath schema1:name ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "A HowTo methodology must have a schema:name" ;
                    sh:minCount 1 ;
                    sh:path schema1:name ;
                    sh:severity sh:Violation ] ] .

